import React from 'react';

import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import { IInterview } from '@apps/Interview/@types/interview.types';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IInterviewListItemProps {
  item: IInterview;
}

const InterviewListItem: React.FC<IInterviewListItemProps> = ({ item }) => {
  return (
    <div className="ms-n2 ny-n3">
      <PohRow>
        <PohCol sm="8">
          <div>
            <strong title={item.name}>{item.name}</strong>
            <small className="ms-2 text-muted">
              <em>
                {item.author.name} {item.author.surname}
              </em>
            </small>
            <small className="d-block text-muted">
              {dateRangeToLocaleString(item.date_start, item.date_finish)}
            </small>
          </div>
        </PohCol>
        <PohCol sm="4">{item.hiking && <HikingBadge hiking={item.hiking} />}</PohCol>
      </PohRow>
    </div>
  );
};

export default InterviewListItem;
